function routeQuery(customerId, query) {
  const shardIndex = hash(customerId) % 16;
  const connection = shardConnections[shardIndex];
  return connection.execute(query);
}

// a query for one customer's orders hits exactly one shard
// a report across all customers must fan out to all sixteen

